INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Abnahmeerklärung immer schriftlich erforderlich?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch mündlich oder stillschweigend erfolgen"}, {"text": "Ja", "correct": false, "because": "Form nicht gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bestätige ich mit einer Abnahmeerklärung?', 3, '[{"text": "Vertragsgemäße Leistung", "correct": true, "because": "Bestätigt Erfüllung"}, {"text": "Zahlungsverpflichtung", "correct": false, "because": "Folge, nicht Inhalt"}, {"text": "Projektstart", "correct": false, "because": "Falscher Zeitpunkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen hat die Abnahmeerklärung?', 5, '[{"text": "Gefahrenübergang", "correct": true, "because": "Risiko geht auf Auftraggeber über"}, {"text": "Vergütung fällig", "correct": true, "because": "Zahlungspflicht beginnt"}, {"text": "Projektende verzögert", "correct": false, "because": "Markiert Abschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Abnahmeerklärung ist bei Werkverträgen Pflicht. b) Sie kann verweigert werden.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Pflicht bei Werkverträgen, Verweigerung bei Mängeln möglich"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Abnahmeerklärung?', 4, '[{"text": "Vertragsdetails", "correct": false, "because": "Müssen geprüft werden"}, {"text": "Mängel", "correct": false, "because": "Wichtig für Verweigerung"}, {"text": "Lieferantenhistorie", "correct": true, "because": "Irrelevant für Abnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine stillschweigende Abnahme zählt?', 2, '[{"text": "Ja", "correct": true, "because": "Durch Verhalten möglich"}, {"text": "Nein", "correct": false, "because": "Rechtlich anerkannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Form ist für eine Abnahmeerklärung typisch?', 3, '[{"text": "Schriftlich", "correct": true, "because": "Klarheit und Nachweis"}, {"text": "Mündlich", "correct": false, "because": "Weniger verbindlich"}, {"text": "Automatisch", "correct": false, "because": "Erfordert Bestätigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Abnahmeerklärung?', 5, '[{"text": "Bestätigung der Leistung", "correct": true, "because": "Kern der Erklärung"}, {"text": "Mängelvorbehalte", "correct": true, "because": "Bei kleinen Mängeln"}, {"text": "Zahlungsdetails", "correct": false, "because": "Folge, nicht Inhalt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Abnahmeerklärung ist nur bei Bauprojekten nötig. b) Sie löst Gewährleistung aus. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Gilt für alle Werkverträge"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abnahmeerklärung unwichtig?', 4, '[{"text": "Vertragsprüfung", "correct": false, "because": "Basis der Abnahme"}, {"text": "Fristeinhaltung", "correct": false, "because": "Rechtlich relevant"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Abnahmekriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich die Abnahme bei kleinen Mängeln verweigern?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei wesentlichen Mängeln"}, {"text": "Ja", "correct": false, "because": "Kleine Mängel kein Grund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt eine schriftliche Abnahmeerklärung?', 4, '[{"text": "Nachweisbarkeit", "correct": true, "because": "Klarer Beweis"}, {"text": "Rechtssicherheit", "correct": true, "because": "Schützt beide Seiten"}, {"text": "Schnellere Bearbeitung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Abnahmeerklärung automatisch erfolgt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Erfordert Bestätigung oder Verhalten"}, {"text": "Ja", "correct": false, "because": "Nicht ohne Aktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Abnahmeerklärung?', 3, '[{"text": "Vertragsgemäßheit", "correct": true, "because": "Hauptkriterium"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Abnahmeerklärung markiert Projektende. b) Sie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht bei Werkverträgen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine mündliche Abnahmeerklärung?', 5, '[{"text": "Schwer nachweisbar", "correct": true, "because": "Keine Dokumentation"}, {"text": "Rechtsunsicherheit", "correct": true, "because": "Streit möglich"}, {"text": "Schneller Prozess", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Abnahmeerklärung sekundär?', 3, '[{"text": "Vertragsprüfung", "correct": false, "because": "Primär"}, {"text": "Mängelprotokoll", "correct": false, "because": "Wichtig"}, {"text": "Design der Urkunde", "correct": true, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beginnt die Gewährleistung mit der Abnahmeerklärung?', 3, '[{"text": "Ja", "correct": true, "because": "Start der Frist"}, {"text": "Nein", "correct": false, "because": "Rechtliche Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Abnahmeerklärung Teilabnahmen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Bei VOB/B möglich"}, {"text": "Nein", "correct": false, "because": "Nicht ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Abnahmeerklärung bei Projekten?', 4, '[{"text": "Bestätigung des Abschlusses", "correct": true, "because": "Markiert Ende"}, {"text": "Start der Planung", "correct": false, "because": "Falscher Zeitpunkt"}, {"text": "Kostenfestlegung", "correct": false, "because": "Folge, nicht Rolle"}]');
